.wsmamabelt__v>.wsmamabelt__zak{text-align:center}
.wsmamabelt__media--vid{aspect-ratio:1/1;background:#fff center/cover no-repeat}.wsmamabelt__media--vid video,.wsmamabelt__media--vid img{width:100%;height:100%;object-fit:cover;display:block}
</style>
<script>
(function(){document.querySelectorAll('.wsmamabelt__media--vid video').forEach(function(v){
  function slika(){if(!v.parentNode)return;var i=document.createElement('img');i.src=v.getAttribute('poster');i.alt='NORIKS MamaBelt';v.parentNode.replaceChild(i,v);}
  v.addEventListener('error',slika,true);var s=v.querySelector('source');if(s)s.addEventListener('error',slika);
  var p=v.play&&v.play();if(p&&p.catch)p.catch(function(){});
});})();
</script>
<script>
(function(){document.querySelectorAll('.wsmamabelt__kar').forEach(function(k){
  var w=document.createElement('div');w.className='wsmamabelt__karw';k.parentNode.insertBefore(w,k);w.appendChild(k);
  ['l','d'].forEach(function(s){var b=document.createElement('button');b.type='button';b.className='wsmamabelt__pus wsmamabelt__pus--'+s;b.setAttribute('aria-label',s==='l'?'Předchozí':'Další');b.innerHTML=s==='l'?'&#8249;':'&#8250;';
    b.addEventListener('click',function(){var x=k.firstElementChild;var d=x?x.getBoundingClientRect().width+22:300;k.scrollBy({left:s==='l'?-d:d,behavior:'smooth'});});w.appendChild(b);});
});})();
</script>
